package com.crosscheck.config;
import com.crosscheck.model.*;import com.crosscheck.repository.*;import com.crosscheck.service.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import java.time.*;
@Configuration public class DataSeeder{@Bean CommandLineRunner seed(UserRepository users,CandidateRepository candidates,NotificationRepository notes,AuthService auth,RiskEngineService risk){return args->{if(users.count()==0){users.save(user("Admin User","admin@crosscheck.com","Admin@123","ADMIN",auth));users.save(user("HR Manager","hr@crosscheck.com","Hr@123","HR",auth));users.save(user("Recruiter User","recruiter@crosscheck.com","Recruiter@123","RECRUITER",auth));}if(candidates.count()==0){Candidate a=candidate("Arjun Reddy","arjun@example.com","9876543210","Senior Software Engineer",7,"Java, Spring Boot, React","TechNova","CodeWorks",30,1800000,1400000,"B.Tech","VTU","2019","8.2",0,88,87);a.setEmploymentStatus("VERIFIED");a.setEducationStatus("VERIFIED");a.setIdentityStatus("VERIFIED");a.setVerificationStatus("VERIFIED");risk.calculate(a);candidates.save(a);Candidate b=candidate("Neha Patel","neha@example.com","9876501234","Data Analyst",3,"Python, SQL, Power BI","DataCore","Insight Labs",60,1100000,800000,"MCA","Bangalore University","2022","78%",1,72,74);risk.calculate(b);candidates.save(b);Candidate c=candidate("Vikram Singh","vikram@example.com","9123456780","DevOps Engineer",5,"AWS, Docker, Kubernetes","CloudAxis",null,90,1600000,1000000,"B.E.",PESU(),"2020","7.6",2,55,60);c.setDuplicateResume(true);risk.calculate(c);candidates.save(c);Candidate d=candidate("Pooja Mehta","pooja@example.com","9988776655","UI/UX Designer",4,"Figma, UX Research, Design Systems","PixelMint","StudioX",30,1200000,950000,"B.Des","NID","2021","8.7",0,92,90);d.setEducationStatus("VERIFIED");d.setIdentityStatus("VERIFIED");risk.calculate(d);candidates.save(d);}if(notes.count()==0){Notification n=new Notification();n.setTitle("Platform ready");n.setMessage("CrossCheck demo workspace is ready with sample candidates.");n.setLevel("LOW");notes.save(n);}};}private User user(String n,String e,String p,String r,AuthService a){User u=new User();u.setName(n);u.setEmail(e);u.setPassword(a.encode(p));u.setRole(r);return u;}private Candidate candidate(String n,String e,String m,String p,double ex,String s,String cur,String prev,int notice,double expected,double current,String degree,String uni,String year,String marks,int offers,int interest,int feedback){Candidate c=new Candidate();c.setName(n);c.setEmail(e);c.setMobileNumber(m);c.setPosition(p);c.setExperienceYears(ex);c.setSkills(s);c.setEducation(degree);c.setCurrentCompany(cur);c.setPreviousCompany(prev);c.setNoticePeriodDays(notice);c.setExpectedSalary(expected);c.setCurrentSalary(current);c.setDegree(degree);c.setUniversity(uni);c.setGraduationYear(year);c.setMarks(marks);c.setActiveOffers(offers);c.setCandidateInterest(interest);c.setInterviewFeedback(feedback);c.setPreviousAcceptanceRate(78);c.setJoiningDate(LocalDate.now().minusYears(2));c.setRelievingDate(LocalDate.now().minusYears(2).minusMonths(1));return c;}private String PESU(){return "PES University";}}
